//! Golden tests against Node's own output. The fixture is generated by
//! `node scripts/generate-js-semantics-fixtures.js` (see that file for the
//! wire format). Regenerate it whenever a rule changes and review the diff —
//! the JS engine is the oracle, not this code.
use super::*;
use base64::Engine;

const FIXTURE: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/js-semantics-fixtures.json"
));

fn fixture() -> JsValue {
    json_parse(FIXTURE).expect("fixture parses with the JS parser")
}

fn entry<'a>(value: &'a JsValue, key: &str) -> &'a JsValue {
    value
        .get(key)
        .unwrap_or_else(|| panic!("fixture entry {key}"))
}

fn entries<'a>(value: &'a JsValue, key: &str) -> &'a [JsValue] {
    match entry(value, key) {
        JsValue::Array(items) => items,
        _ => panic!("fixture entry {key} is an array"),
    }
}

fn text_value(value: &JsValue) -> String {
    js_to_string(value).to_string_lossy()
}

fn number_from_bits(value: &JsValue) -> f64 {
    let text = text_value(value);
    f64::from_bits(u64::from_str_radix(&text, 16).unwrap_or_else(|_| panic!("bits {text}")))
}

fn decode_base64(value: &JsValue) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD
        .decode(text_value(value))
        .expect("base64")
}

/// Decode the fixture's tagged value encoding into a `JsValue`.
fn wire_decode(value: &JsValue) -> JsValue {
    match value {
        JsValue::Object(_) => {
            let tag = text_value(value.get("t").expect("wire tag wrapper"));
            match tag.as_str() {
                "undefined" => JsValue::Undefined,
                "null" => JsValue::Null,
                "boolean" => match value.get("v") {
                    Some(JsValue::Bool(flag)) => JsValue::Bool(*flag),
                    _ => panic!("boolean wire payload"),
                },
                "number" => JsValue::Number(number_from_bits(entry(value, "v"))),
                "date" => JsValue::Date(number_from_bits(entry(value, "v"))),
                "string" => JsValue::String(match entry(value, "v") {
                    JsValue::String(text) => text.clone(),
                    _ => panic!("string wire payload"),
                }),
                "bytes" => JsValue::Bytes(decode_base64(entry(value, "v"))),
                "array" => JsValue::Array(
                    match entry(value, "v") {
                        JsValue::Array(items) => items,
                        _ => panic!("array wire payload"),
                    }
                    .iter()
                    .map(wire_decode)
                    .collect(),
                ),
                "object" => JsValue::Object(
                    match entry(value, "v") {
                        JsValue::Array(items) => items,
                        _ => panic!("object wire payload"),
                    }
                    .iter()
                    .map(|pair| match pair {
                        JsValue::Array(parts) => (
                            match &parts[0] {
                                JsValue::String(text) => text.clone(),
                                _ => panic!("object wire key"),
                            },
                            wire_decode(&parts[1]),
                        ),
                        _ => panic!("object wire pair"),
                    })
                    .collect(),
                ),
                other => panic!("unknown wire tag {other}"),
            }
        }
        _ => panic!("wire value is an object"),
    }
}

#[test]
fn string_coercion_matches_node() {
    let fixture = fixture();
    for case in entries(&fixture, "toString") {
        let value = wire_decode(entry(case, "value"));
        assert_eq!(text_value(&value), text_value(entry(case, "out")));
    }
}

#[test]
fn number_coercion_matches_node() {
    let fixture = fixture();
    for case in entries(&fixture, "toNumber") {
        let input = text_value(entry(case, "in"));
        let expected = number_from_bits(entry(case, "out"));
        let actual = js_string_to_number(&input);
        assert!(
            (actual.is_nan() && expected.is_nan()) || (actual.to_bits() == expected.to_bits()),
            "Number({input:?}) = {actual:?}, expected {expected:?}"
        );
    }
}

#[test]
fn number_formatting_matches_node() {
    let fixture = fixture();
    for case in entries(&fixture, "toString") {
        let value = wire_decode(entry(case, "value"));
        if let JsValue::Number(number) = value {
            assert_eq!(
                number_to_string(number),
                text_value(entry(case, "out")),
                "String({number:?})"
            );
        }
    }
}

#[test]
fn trim_matches_node() {
    let fixture = fixture();
    for case in entries(&fixture, "trim") {
        let input = match entry(case, "in") {
            JsValue::String(text) => text.clone(),
            _ => panic!("trim input"),
        };
        assert_eq!(
            input.trim().to_string_lossy(),
            text_value(entry(case, "out")),
            "trim({input:?})"
        );
        assert_eq!(
            input.trim_start().to_string_lossy(),
            text_value(entry(case, "start")),
            "trimStart({input:?})"
        );
        assert_eq!(
            input.trim_end().to_string_lossy(),
            text_value(entry(case, "end")),
            "trimEnd({input:?})"
        );
    }
}

#[test]
fn json_stringify_matches_node() {
    let fixture = fixture();
    for case in entries(&fixture, "jsonStringify") {
        let value = wire_decode(entry(case, "value"));
        let expected = match entry(case, "out") {
            JsValue::Null => None,
            JsValue::String(text) => Some(text.to_string_lossy()),
            _ => panic!("jsonStringify out"),
        };
        assert_eq!(
            json_stringify(&value),
            expected,
            "JSON.stringify({})",
            json_stringify_or_undefined(&value)
        );
    }
}

#[test]
fn json_parse_matches_node() {
    let fixture = fixture();
    for case in entries(&fixture, "jsonParseValid") {
        let input = match entry(case, "in") {
            JsValue::String(text) => text.to_string_lossy(),
            _ => panic!("jsonParse input"),
        };
        let parsed = json_parse(&input).unwrap_or_else(|error| panic!("{input:?}: {error}"));
        assert_eq!(
            json_stringify_or_undefined(&parsed),
            text_value(entry(case, "out")),
            "JSON.parse({input:?})"
        );
    }
    for case in entries(&fixture, "jsonParseInvalid") {
        let input = match case {
            JsValue::String(text) => text.to_string_lossy(),
            _ => panic!("invalid input"),
        };
        assert!(
            json_parse(&input).is_err(),
            "JSON.parse({input:?}) should throw"
        );
    }
}

#[test]
fn serde_conversion_matches_the_documented_contract() {
    let fixture = fixture();
    for case in entries(&fixture, "jsonStringify") {
        let value = wire_decode(entry(case, "value"));
        let text = json_stringify_or_undefined(&value);
        if text == "undefined" {
            continue;
        }
        // Lone surrogates are the only documented loss; fixture cases without
        // them must match exactly.
        if text.contains("\\ud8")
            || text.contains("\\ud9")
            || text.contains("\\uda")
            || text.contains("\\udb")
            || text.contains("\\udc")
            || text.contains("\\udd")
            || text.contains("\\ude")
            || text.contains("\\udf")
        {
            continue;
        }
        let parsed: serde_json::Value =
            serde_json::from_str(&text).unwrap_or_else(|error| panic!("{text}: {error}"));
        assert_eq!(to_serde(&value), parsed, "{text}");
        assert_eq!(
            json_stringify(&from_serde(&to_serde(&value))).unwrap(),
            text
        );
    }
}
